import csv, json, math
from collections import defaultdict, Counter
BASE='/app'

def read_csv(path):
    with open(path,newline='') as f:
        return list(csv.DictReader(f))

config=json.load(open(f'{BASE}/data/config.json'))
sol=read_csv(f'{BASE}/submissions/solution.csv')
obsw=read_csv(f'{BASE}/data/observation_windows.csv')
dlw=read_csv(f'{BASE}/data/downlink_windows.csv')
reqs=read_csv(f'{BASE}/data/requests.csv')
sats=read_csv(f'{BASE}/data/satellites.csv')
scens=read_csv(f'{BASE}/data/scenarios.csv')
qual=read_csv(f'{BASE}/data/scenario_observation_quality.csv')
mults=read_csv(f'{BASE}/data/scenario_downlink_multipliers.csv')
ing=read_csv(f'{BASE}/data/region_ingest_capacity.csv')
gs=read_csv(f'{BASE}/data/ground_stations.csv')

# data maps
sat_by={r['satellite_id']:{k:(float(v) if k not in ('satellite_id','orbit_plane') else v) for k,v in r.items()} for r in sats}
req_by={r['request_id']:{k:(float(v) if k in ('data_gb','mission_value') else int(v) if k in ('critical','deadline_slot') else v) for k,v in r.items()} for r in reqs}
scen_prob={r['scenario_id']:float(r['probability']) for r in scens}
scen_target={r['scenario_id']:float(r['target_profit']) for r in scens}
obs_detail={(r['satellite_id'],int(r['slot']),r['request_id']):{**r,'slot':int(r['slot']),'energy_kwh':float(r['energy_kwh']),'thermal_load':float(r['thermal_load']),'quality_score':float(r['quality_score'])} for r in obsw}
dl_detail={(r['satellite_id'],int(r['slot']),r['ground_station']):{**r,'slot':int(r['slot']),'base_capacity_gb':float(r['base_capacity_gb'])} for r in dlw}
qual_by={(r['scenario_id'],r['request_id']):{'usable':int(r['usable']),'value_multiplier':float(r['value_multiplier'])} for r in qual}
mult_by={(r['scenario_id'],r['ground_station'],int(r['slot'])):float(r['capacity_multiplier']) for r in mults}
ing_by={(r['scenario_id'],r['disaster_region'],int(r['slot'])):float(r['max_ingest_gb']) for r in ing}
antenna={r['ground_station']:int(r['antenna_count']) for r in gs}
scenarios=list(scen_prob)

# parse solution
obs_rows=[]
dl_rows=[]
for line,row in enumerate(sol,start=2):
    if row['row_type']=='observe':
        obs_rows.append({'line':line,'satellite_id':row['satellite_id'],'slot':int(row['slot']),'request_id':row['request_id']})
    else:
        dl_rows.append({'line':line,'scenario_id':row['scenario_id'],'satellite_id':row['satellite_id'],'slot':int(row['slot']),'request_id':row['request_id'],'ground_station':row['ground_station'],'quantity':float(row['quantity'])})

viol=[]
# observation structural/temporal constraints
obs_by_req=defaultdict(list)
obs_by_sat_slot=defaultdict(list)
obs_by_sat=defaultdict(list)
obs_req_sat={} # request -> (sat,slot)
for r in obs_rows:
    obs_by_req[r['request_id']].append(r)
    obs_by_sat_slot[(r['satellite_id'],r['slot'])].append(r)
    obs_by_sat[r['satellite_id']].append(r)
for req, rows in obs_by_req.items():
    if len(rows)>1:
        viol.append(('observe_at_most_once', req, [x['line'] for x in rows], len(rows), '<=1 observation rows'))
for key, rows in obs_by_sat_slot.items():
    if len(rows)>1:
        viol.append(('one_observation_per_satellite_slot', key, [x['line'] for x in rows], len(rows), '<=1'))
for sat, rows in obs_by_sat.items():
    if len(rows)>config['max_observations_per_satellite']:
        viol.append(('max_observations_per_satellite', sat, len(rows), config['max_observations_per_satellite'], '<='))
    rows=sorted(rows,key=lambda x:x['slot'])
    for a,b in zip(rows,rows[1:]):
        if b['slot']==a['slot']+1:
            da=obs_detail[(a['satellite_id'],a['slot'],a['request_id'])]
            db=obs_detail[(b['satellite_id'],b['slot'],b['request_id'])]
            if da['slew_class']=='high' or db['slew_class']=='high':
                viol.append(('high_slew_recovery', sat, (a['line'],b['line']), f\"slots {a['slot']},{b['slot']} with slews {da['slew_class']},{db['slew_class']}\", 'need recovery slot'))
for r in obs_rows:
    obs_req_sat[r['request_id']] = (r['satellite_id'], r['slot'])

# downlink aggregate by scenario/contact/request etc
by_scen_contact_req=defaultdict(float)
by_scen_contact_lines=defaultdict(list)
by_scen_sat_slot_any=defaultdict(float)
by_scen_station_slot_contacts=defaultdict(set)
by_scen_station_slot_qty=defaultdict(float)
by_scen_region_slot_qty=defaultdict(float)
by_scen_req_total=defaultdict(float)
by_scen_req_sat_qty=defaultdict(float)
req_slot_cum=defaultdict(list)
for r in dl_rows:
    key=(r['scenario_id'],r['satellite_id'],r['slot'],r['ground_station'],r['request_id'])
    by_scen_contact_req[key]+=r['quantity']
    by_scen_contact_lines[key].append(r['line'])
    by_scen_sat_slot_any[(r['scenario_id'],r['satellite_id'],r['slot'])]+=r['quantity']
    if r['quantity']>config['quantity_tolerance']:
        by_scen_station_slot_contacts[(r['scenario_id'],r['ground_station'],r['slot'])].add(r['satellite_id'])
    by_scen_station_slot_qty[(r['scenario_id'],r['ground_station'],r['slot'])]+=r['quantity']
    by_scen_region_slot_qty[(r['scenario_id'], req_by[r['request_id']]['disaster_region'], r['slot'])]+=r['quantity']
    by_scen_req_total[(r['scenario_id'],r['request_id'])]+=r['quantity']
    by_scen_req_sat_qty[(r['scenario_id'],r['request_id'],r['satellite_id'])]+=r['quantity']
    req_slot_cum[(r['scenario_id'],r['request_id'])].append((r['slot'],r['quantity'],r['line']))

# contact capacity per scenario-contact and observing restrictions
for (sc,sat,slot,gsn,req),qty in by_scen_contact_req.items():
    c=dl_detail[(sat,slot,gsn)]
    cap=c['base_capacity_gb']*mult_by[(sc,gsn,slot)]
    # contact cap later aggregated per contact
    obs=obs_req_sat.get(req)
    if obs is None:
        viol.append(('downlink_unobserved_request', (sc,req), by_scen_contact_lines[(sc,sat,slot,gsn,req)], qty, '0 unless request observed'))
    else:
        if obs[0]"'!=sat:
            viol.append(('"'wrong_satellite_downlink', (sc,req,sat,slot,gsn), by_scen_contact_lines[(sc,sat,slot,gsn,req)], sat, f\"must equal observing satellite {obs[0]}\"))
        if slot <= obs[1]:
            viol.append(('downlink_before_observation', (sc,req,sat,slot,gsn), by_scen_contact_lines[(sc,sat,slot,gsn,req)], slot, f\"> observation slot {obs[1]}\"))
        if slot > req_by[req]['deadline_slot']:
            viol.append(('downlink_after_deadline', (sc,req,sat,slot,gsn), by_scen_contact_lines[(sc,sat,slot,gsn,req)], slot, f\"<= deadline {req_by[req]['deadline_slot']}\"))
# contact capacity aggregated
by_contact=defaultdict(float)
by_contact_lines=defaultdict(list)
for r in dl_rows:
    k=(r['scenario_id'],r['satellite_id'],r['slot'],r['ground_station'])
    by_contact[k]+=r['quantity']
    by_contact_lines[k].append(r['line'])
for k,qty in by_contact.items():
    sc,sat,slot,gsn=k
    cap=dl_detail[(sat,slot,gsn)]['base_capacity_gb']*mult_by[(sc,gsn,slot)]
    if qty > cap + config['quantity_tolerance']:
        viol.append(('contact_capacity',k,by_contact_lines[k],qty,cap))
# station antenna limit
for k,sats_used in by_scen_station_slot_contacts.items():
    if len(sats_used) > antenna[k[1]]:
        viol.append(('station_antenna_limit',k,sorted(sats_used),len(sats_used),antenna[k[1]]))
# observe/downlink same slot
for sc in scenarios:
    for obs in obs_rows:
        qty=by_scen_sat_slot_any.get((sc,obs['satellite_id'],obs['slot']),0.0)
        if qty > config['quantity_tolerance']:
            viol.append(('observe_and_downlink_same_slot',(sc,obs['satellite_id'],obs['slot']),obs['line'],qty,'0 downlink when observing'))
# request-level totals and inventory over time
for sc in scenarios:
    for req in req_by:
        total=by_scen_req_total.get((sc,req),0.0)
        size=req_by[req]['data_gb']
        if total > size + config['quantity_tolerance']:
            viol.append(('request_total_downlink_exceeds_size',(sc,req),total,size,'<='))
        # if request never observed, total should be 0 checked above
        # cumulative by slot after obs time
        obs=obs_req_sat.get(req)
        cum=0.0
        for slot,qty,line in sorted(req_slot_cum.get((sc,req),[])):
            cum += qty
            if cum > size + config['quantity_tolerance']:
                viol.append(('request_cumulative_downlink_exceeds_size',(sc,req,slot),line,cum,size))
# region ingest
for k,qty in by_scen_region_slot_qty.items():
    cap=ing_by[k]
    if qty > cap + config['quantity_tolerance']:
        viol.append(('region_ingest_capacity',k,qty,cap,'<='))
# memory / energy / thermal
horizon=config['planning_horizon_slots']
roll=config['thermal_rolling_window_slots']
obs_by_sat_slot_exact={(r['satellite_id'],r['slot']):r for r in obs_rows}
for sc in scenarios:
    for sat,satd in sat_by.items():
        mem=satd['initial_memory_gb']
        energy=satd['initial_energy_kwh']
        therm_hist=[]
        observed_data_cum=0.0
        downlinked_data_cum=0.0
        # request-specific onboard inventory for this sat in this scenario
        for t in range(1,horizon+1):
            obs_load=0.0
            obs_energy=0.0
            obs_data=0.0
            if (sat,t) in obs_by_sat_slot_exact:
                orow=obs_by_sat_slot_exact[(sat,t)]
                od=obs_detail[(sat,t,orow['request_id'])]
                obs_load=od['thermal_load']
                obs_energy=od['energy_kwh']
                obs_data=req_by[orow['request_id']]['data_gb']
            dl_qty=sum(q for (ssc,ssat,slot,gs),q in by_contact.items() if ssc==sc and ssat==sat and slot==t)
            mem = mem + obs_data - dl_qty
            observed_data_cum += obs_data
            downlinked_data_cum += dl_qty
            if mem < -config['quantity_tolerance'] or mem > satd['memory_capacity_gb'] + config['quantity_tolerance']:
                viol.append(('memory_bounds',(sc,sat,t),mem,[0.0,satd['memory_capacity_gb']],'within'))
            if downlinked_data_cum > observed_data_cum + config['quantity_tolerance']:
                viol.append(('satellite_inventory_conservation',(sc,sat,t),downlinked_data_cum,observed_data_cum,'downlinked <= observed cumulative'))
            energy = min(satd['energy_capacity_kwh'], energy - obs_energy - satd['downlink_energy_kwh_per_gb']*dl_qty + satd['solar_recharge_kwh_per_slot'])
            if energy < config['reserve_energy_kwh'] - config['quantity_tolerance'] or energy > satd['energy_capacity_kwh'] + config['quantity_tolerance']:
                viol.append(('energy_bounds',(sc,sat,t),energy,[config['reserve_energy_kwh'],satd['energy_capacity_kwh']],'within'))
            therm = obs_load + satd['downlink_thermal_per_gb']*dl_qty
            therm_hist.append((t,therm))
            window=sum(v for _,v in therm_hist[-roll:])
            if window > satd['thermal_limit_rolling'] + config['quantity_tolerance']:
                viol.append(('rolling_thermal_limit',(sc,sat,t),window,satd['thermal_limit_rolling'],'<='))
# service floors, profit
pair_members=defaultdict(list)
for r,d in req_by.items():
    pair_members[d['stereo_pair_id']].append(r)
pair_members={p:members for p,members in pair_members.items() if p}
profits={}
service={}
for sc in scenarios:
    delivered=[]
    delivered_set=set()
    total_value=0.0
    usable_total_value=0.0
    usable_critical=0
    delivered_critical=0
    regions=set()
    for req,d in req_by.items():
        q=qual_by[(sc,req)]
        usable=q['usable']
        val=d['mission_value']*q['value_multiplier'] if usable else 0.0
        usable_total_value += val
        if d['critical'] and usable:
            usable_critical += 1
        total=by_scen_req_total.get((sc,req),0.0)
        is_delivered = usable and (total >= d['data_gb'] - config['quantity_tolerance']) and (total <= d['data_gb'] + config['quantity_tolerance'])
        if is_delivered:
            delivered.append(req)
            delivered_set.add(req)
            regions.add(d['disaster_region'])
            total_value += val
